"""LLM client for OpenAI-compatible APIs."""

import os
from typing import Callable

import requests
from dotenv import load_dotenv

load_dotenv()


class LLMError(Exception):
    """Raised when an LLM API call fails."""

    def __init__(self, status_code: int, body: str):
        self.status_code = status_code
        self.body = body
        super().__init__(f"LLM API error: status={status_code}, body={body[:200]}")


class LLMClient:
    """Client for OpenAI-compatible chat completions API."""

    def __init__(self):
        self.base_url = os.getenv("MODEL_BASE_URL", "").rstrip("/")
        self.api_key = os.getenv("MODEL_API_KEY", "")
        self.model_name = os.getenv("MODEL_NAME", "")

        if not self.base_url:
            raise ValueError("MODEL_BASE_URL must be set")
        if not self.api_key:
            raise ValueError("MODEL_API_KEY must be set")
        if not self.model_name:
            raise ValueError("MODEL_NAME must be set")

        self.calls = 0
        self.prompt_tokens = 0
        self.completion_tokens = 0

    def complete(self, system: str, user: str, json_mode: bool = False) -> str:
        """Call the chat completions endpoint."""
        url = f"{self.base_url}/chat/completions"
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
        }
        payload = {
            "model": self.model_name,
            "messages": [
                {"role": "system", "content": system},
                {"role": "user", "content": user},
            ],
            "temperature": 0.2,
        }
        if json_mode:
            payload["response_format"] = {"type": "json_object"}

        response = requests.post(url, headers=headers, json=payload, timeout=60)

        if not response.ok:
            raise LLMError(response.status_code, response.text[:200])

        data = response.json()
        content = data["choices"][0]["message"]["content"]

        usage = data.get("usage", {})
        self.calls += 1
        self.prompt_tokens += usage.get("prompt_tokens", 0)
        self.completion_tokens += usage.get("completion_tokens", 0)

        return content


class FakeLLMClient:
    """Fake LLM client for testing."""

    def __init__(self, response: str | Callable[[str, str], str]):
        self._response = response
        self.calls = 0
        self.prompt_tokens = 0
        self.completion_tokens = 0

    def complete(self, system: str, user: str, json_mode: bool = False) -> str:
        self.calls += 1
        if callable(self._response):
            return self._response(system, user)
        return self._response


def get_llm() -> LLMClient | FakeLLMClient:
    """Get the appropriate LLM client based on LLM_MODE."""
    mode = os.getenv("LLM_MODE", "live").lower()
    if mode == "fake":
        return FakeLLMClient("Fake response")
    return LLMClient()

"""Tests for the LLM client."""

import os
from unittest.mock import Mock, patch

import pytest

from app.llm import FakeLLMClient, LLMClient, LLMError, get_llm


class TestFakeLLMClient:
    """Tests for FakeLLMClient."""

    def test_fake_client_returns_static_response(self):
        client = FakeLLMClient("Static response")
        result = client.complete("system prompt", "user prompt")
        assert result == "Static response"
        assert client.calls == 1

    def test_fake_client_returns_callable_response(self):
        def responder(system: str, user: str) -> str:
            return f"System: {system}, User: {user}"

        client = FakeLLMClient(responder)
        result = client.complete("sys", "usr")
        assert result == "System: sys, User: usr"
        assert client.calls == 1

    def test_fake_client_tracks_calls(self):
        client = FakeLLMClient("response")
        client.complete("sys", "usr")
        client.complete("sys", "usr")
        assert client.calls == 2

    def test_fake_client_json_mode_ignored(self):
        client = FakeLLMClient("response")
        result = client.complete("sys", "usr", json_mode=True)
        assert result == "response"


class TestLLMClient:
    """Tests for LLMClient (mocked, no real network calls)."""

    @patch.dict(os.environ, {
        "MODEL_BASE_URL": "https://api.example.com",
        "MODEL_API_KEY": "test-key",
        "MODEL_NAME": "test-model",
    })
    def test_client_initialization(self):
        client = LLMClient()
        assert client.base_url == "https://api.example.com"
        assert client.api_key == "test-key"
        assert client.model_name == "test-model"
        assert client.calls == 0
        assert client.prompt_tokens == 0
        assert client.completion_tokens == 0

    @patch.dict(os.environ, {
        "MODEL_BASE_URL": "https://api.example.com",
        "MODEL_API_KEY": "test-key",
        "MODEL_NAME": "test-model",
    })
    @patch("requests.post")
    def test_successful_completion(self, mock_post):
        mock_response = Mock()
        mock_response.ok = True
        mock_response.json.return_value = {
            "choices": [{"message": {"content": "Hello world"}}],
            "usage": {"prompt_tokens": 10, "completion_tokens": 5},
        }
        mock_post.return_value = mock_response

        client = LLMClient()
        result = client.complete("You are helpful", "Say hello")

        assert result == "Hello world"
        assert client.calls == 1
        assert client.prompt_tokens == 10
        assert client.completion_tokens == 5
        mock_post.assert_called_once()

    @patch.dict(os.environ, {
        "MODEL_BASE_URL": "https://api.example.com",
        "MODEL_API_KEY": "test-key",
        "MODEL_NAME": "test-model",
    })
    @patch("requests.post")
    def test_successful_completion_no_usage(self, mock_post):
        mock_response = Mock()
        mock_response.ok = True
        mock_response.json.return_value = {
            "choices": [{"message": {"content": "Hello world"}}],
        }
        mock_post.return_value = mock_response

        client = LLMClient()
        result = client.complete("You are helpful", "Say hello")

        assert result == "Hello world"
        assert client.calls == 1
        assert client.prompt_tokens == 0
        assert client.completion_tokens == 0

    @patch.dict(os.environ, {
        "MODEL_BASE_URL": "https://api.example.com",
        "MODEL_API_KEY": "test-key",
        "MODEL_NAME": "test-model",
    })
    @patch("requests.post")
    def test_http_error_raises_llm_error(self, mock_post):
        mock_response = Mock()
        mock_response.ok = False
        mock_response.status_code = 401
        mock_response.text = "Unauthorized: invalid API key"
        mock_post.return_value = mock_response

        client = LLMClient()
        with pytest.raises(LLMError) as exc_info:
            client.complete("sys", "usr")

        assert exc_info.value.status_code == 401
        assert "401" in str(exc_info.value)
        assert "Unauthorized" in str(exc_info.value)
        assert "test-key" not in str(exc_info.value)

    @patch.dict(os.environ, {
        "MODEL_BASE_URL": "https://api.example.com",
        "MODEL_API_KEY": "test-key",
        "MODEL_NAME": "test-model",
    })
    @patch("requests.post")
    def test_error_body_truncated_to_200_chars(self, mock_post):
        mock_response = Mock()
        mock_response.ok = False
        mock_response.status_code = 500
        mock_response.text = "x" * 300
        mock_post.return_value = mock_response

        client = LLMClient()
        with pytest.raises(LLMError) as exc_info:
            client.complete("sys", "usr")

        assert len(exc_info.value.body) == 200

    @patch.dict(os.environ, {
        "MODEL_BASE_URL": "https://api.example.com",
        "MODEL_API_KEY": "test-key",
        "MODEL_NAME": "test-model",
    })
    @patch("requests.post")
    def test_json_mode_adds_response_format(self, mock_post):
        mock_response = Mock()
        mock_response.ok = True
        mock_response.json.return_value = {
            "choices": [{"message": {"content": '{"key": "value"}'}}],
            "usage": {},
        }
        mock_post.return_value = mock_response

        client = LLMClient()
        client.complete("sys", "usr", json_mode=True)

        call_args = mock_post.call_args
        payload = call_args.kwargs["json"]
        assert payload["response_format"] == {"type": "json_object"}

    @patch.dict(os.environ, {
        "MODEL_BASE_URL": "https://api.example.com",
        "MODEL_API_KEY": "test-key",
        "MODEL_NAME": "test-model",
    })
    @patch("requests.post")
